INSERT INTO pre_condition (id, pre_condition_description, script_id, created_date, updated_at) VALUES ('d7d2554e-d363-4b54-b106-236d7e136331', 'VTS binaries must be installed in DUT', '5d2f884b-ffa6-417e-84f6-3a3aac6275ed', '2026-10-14 06:18:33.900301', '2026-10-14 06:18:33.900316');
