INSERT INTO pre_condition (id, pre_condition_description, script_id, created_date, updated_at) VALUES ('ee14fee7-5100-40bc-b6c7-ce0ed223fbd8', '1.tdk_mediapipelinetests application should be installed in the DUT
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f58c5c60-9303-46b9-88f2-cfe4aa6e0c6a', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', '332184a0-f01b-4fc7-9328-6f8149e981f4', '2026-10-31 19:55:48.350547', '2026-10-31 19:55:48.350549');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2626a6a6-a493-4fd7-8c1c-72df8fcf6607', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', '332184a0-f01b-4fc7-9328-6f8149e981f4', '2026-10-31 19:55:48.351314', '2026-10-31 19:55:48.351315');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7c5b3276-d302-4c91-916e-7fe1dea8ec83', 'Build the 4K HLS HEVC successive-playback test URLs', 'Combine the configured 4K HLS video source URL, execution identifiers, logging information, the close operation, and autotest: "true" into the HTML HLS player test URL. Generate one such URL per iteration, where the number of iterations is Succesive_playback_iterations; every URL carries the same stream, so the stream is played that many times in succession.', 'A list of 4K HLS HEVC player test URLs should be generated whose length equals Succesive_playback_iterations, with each entry pointing to the same stream.', '332184a0-f01b-4fc7-9328-6f8149e981f4', '2026-10-31 19:55:48.351511', '2026-10-31 19:55:48.351512');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ab1e391f-e4dc-4a4b-bda1-f8fa31d83578', 'Store the player URLs in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated 4K HLS HEVC successive-playback URL list>"}}. The player application reads this list and plays the URLs one after another.', 'The URL list should be stored successfully in PersistentStore.', '332184a0-f01b-4fc7-9328-6f8149e981f4', '2026-10-31 19:55:48.352081', '2026-10-31 19:55:48.352082');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b8105456-d210-42b3-b78f-f9f71f43837d', 'Check whether the HTML player is installed', 'Request the installed package list with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"} and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', '332184a0-f01b-4fc7-9328-6f8149e981f4', '2026-10-31 19:55:48.352654', '2026-10-31 19:55:48.352655');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e31101a4-d1e0-41ca-b90b-993fbafff4cd', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', '332184a0-f01b-4fc7-9328-6f8149e981f4', '2026-10-31 19:55:48.353205', '2026-10-31 19:55:48.353206');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bb5c9d4e-495d-4a76-a153-e196bd7e782f', 'Download the HTML player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', '332184a0-f01b-4fc7-9328-6f8149e981f4', '2026-10-31 19:55:48.353957', '2026-10-31 19:55:48.353958');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('064ca342-5afa-4d1d-a3de-1b4fbf76a520', 'Install the HTML player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', '332184a0-f01b-4fc7-9328-6f8149e981f4', '2026-10-31 19:55:48.354595', '2026-10-31 19:55:48.354596');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b87fac71-aaac-428a-9668-67f2141e595c', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', '332184a0-f01b-4fc7-9328-6f8149e981f4', '2026-10-31 19:55:48.355266', '2026-10-31 19:55:48.355267');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('434f720e-a3cd-4eeb-9e63-f80605c0a59b', 'Launch the HTML player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', '332184a0-f01b-4fc7-9328-6f8149e981f4', '2026-10-31 19:55:48.355887', '2026-10-31 19:55:48.355888');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5680226c-9b49-4a8f-ba33-6127363d0ce3', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The HTML player should appear as an active loaded application.', '332184a0-f01b-4fc7-9328-6f8149e981f4', '2026-10-31 19:55:48.356074', '2026-10-31 19:55:48.356074');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b79ba56a-01a9-4ed0-a275-8b111ecab8ab', 'Validate the successive 4K HLS HEVC playback', 'Monitor the REST API application log until the final test result is reported. Count the entries containing Video Player Playing (one per playback), collect each STREAM <number> PLAYBACK RESULT : SUCCESS or FAILURE entry, and check the final TEST RESULT entry.', 'The number of Video Player Playing entries should equal Succesive_playback_iterations, every STREAM <number> entry from 1 to that count should report SUCCESS, and the final result should be TEST RESULT: SUCCESS.', '332184a0-f01b-4fc7-9328-6f8149e981f4', '2026-10-31 19:55:48.356617', '2026-10-31 19:55:48.356617');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0e28b7c4-2ec2-4975-8948-81c43d87898d', 'Validate the post-playback resource usage', 'After successful playback, run the resource-usage validation and evaluate the returned CPU load and memory usage.', 'CPU load and memory usage should be returned and should remain within the configured limits.', '332184a0-f01b-4fc7-9328-6f8149e981f4', '2026-10-31 19:55:48.357183', '2026-10-31 19:55:48.357184');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('30be77d6-e2d1-40d3-9d03-698d2bee2476', 'Terminate the HTML player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The HTML player should terminate successfully.', '332184a0-f01b-4fc7-9328-6f8149e981f4', '2026-10-31 19:55:48.357900', '2026-10-31 19:55:48.357901');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('68b37ba1-4621-4ab1-824e-f0b74364d6b4', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', '332184a0-f01b-4fc7-9328-6f8149e981f4', '2026-10-31 19:55:48.358528', '2026-10-31 19:55:48.358529');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('06ab35bb-c098-4fab-8c36-a682f7c3f235', 'STEP 1', '1.Initiate SSH connection to execute command remotely.
