INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b80231d1-d0ad-4ee7-aed8-3a06b9da6a59', 'Check whether the HTML player is installed', 'Request the installed package list with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"} and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', '6215dffb-eb18-4908-b412-ff97d73592f0', '2026-10-31 20:11:08.383400', '2026-10-31 20:11:08.383401');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('290c8e62-b7a4-4933-9705-ce12d1951508', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', '6215dffb-eb18-4908-b412-ff97d73592f0', '2026-10-31 20:11:08.383593', '2026-10-31 20:11:08.383594');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9fb51474-820d-4225-b85d-ef45bd34965e', 'Download the HTML player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', '6215dffb-eb18-4908-b412-ff97d73592f0', '2026-10-31 20:11:08.384390', '2026-10-31 20:11:08.384390');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2b526a57-07c9-4e4e-9204-b939a2d52dbe', 'Install the HTML player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', '6215dffb-eb18-4908-b412-ff97d73592f0', '2026-10-31 20:11:08.385378', '2026-10-31 20:11:08.385379');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fe17d101-3763-40c0-83dd-92f83475854e', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', '6215dffb-eb18-4908-b412-ff97d73592f0', '2026-10-31 20:11:08.386271', '2026-10-31 20:11:08.386272');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('19871ffd-584e-4721-9263-3909c1de5b55', 'Launch the HTML player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', '6215dffb-eb18-4908-b412-ff97d73592f0', '2026-10-31 20:11:08.387116', '2026-10-31 20:11:08.387116');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('529808c8-511b-43a2-856b-42025d338c1a', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The HTML player should appear as an active loaded application.', '6215dffb-eb18-4908-b412-ff97d73592f0', '2026-10-31 20:11:08.387868', '2026-10-31 20:11:08.387869');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f3706396-2843-40da-9605-6676682643cb', 'Validate the successive WEBM playback', 'Monitor the REST API application log until the final test result is reported. Count the entries containing Video Player Playing (one per playback), collect each STREAM <number> PLAYBACK RESULT : SUCCESS or FAILURE entry, and check the final TEST RESULT entry.', 'The number of Video Player Playing entries should equal Succesive_playback_iterations, every STREAM <number> entry from 1 to that count should report SUCCESS, and the final result should be TEST RESULT: SUCCESS.', '6215dffb-eb18-4908-b412-ff97d73592f0', '2026-10-31 20:11:08.388559', '2026-10-31 20:11:08.388560');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c1d2931a-8406-4eb4-96cd-9222a6a6dfca', 'Validate the post-playback resource usage', 'After successful playback, run the resource-usage validation and evaluate the returned CPU load and memory usage.', 'CPU load and memory usage should be returned and should remain within the configured limits.', '6215dffb-eb18-4908-b412-ff97d73592f0', '2026-10-31 20:11:08.389246', '2026-10-31 20:11:08.389247');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('824c7eda-dee3-4c6f-92c9-138b6f50e2e1', 'Terminate the HTML player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The HTML player should terminate successfully.', '6215dffb-eb18-4908-b412-ff97d73592f0', '2026-10-31 20:11:08.390006', '2026-10-31 20:11:08.390007');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5ec1175a-706b-44fe-b218-155297a7e885', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', '6215dffb-eb18-4908-b412-ff97d73592f0', '2026-10-31 20:11:08.390711', '2026-10-31 20:11:08.390711');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b53758ce-a015-4d32-8f8d-7fb2e943595c', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', 'ba04674e-20bd-4b1b-909f-19a80ddb796a', '2026-10-31 19:32:39.384326', '2026-10-31 19:32:39.384328');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('94820607-7712-41cb-b75e-afaeb82755c2', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', 'ba04674e-20bd-4b1b-909f-19a80ddb796a', '2026-10-31 19:32:39.387736', '2026-10-31 19:32:39.387738');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('78cf53bd-fdf9-4827-9533-e7adafde80e9', 'Build the HEVC successive-playback test URLs', 'Combine the configured HEVC 30 fps video source URL, execution identifiers, logging information, the close operation, and autotest: "true" into the HTML video player test URL. Generate one such URL per iteration, where the number of iterations is Succesive_playback_iterations; every URL carries the same stream, so the stream is played that many times in succession.', 'A list of HEVC player test URLs should be generated whose length equals Succesive_playback_iterations, with each entry pointing to the same stream.', 'ba04674e-20bd-4b1b-909f-19a80ddb796a', '2026-10-31 19:32:39.390337', '2026-10-31 19:32:39.390338');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ad5a509e-7315-4ee7-ae45-f44063065e99', 'Store the player URLs in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated HEVC successive-playback URL list>"}}. The player application reads this list and plays the URLs one after another.', 'The URL list should be stored successfully in PersistentStore.', 'ba04674e-20bd-4b1b-909f-19a80ddb796a', '2026-10-31 19:32:39.391134', '2026-10-31 19:32:39.391136');
