INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('669eb713-0171-4d3f-9f28-e9055995dc07', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', '3f4d2bb5-b10a-4e83-9d8b-ed0fb7869607', '2026-10-31 19:49:08.746925', '2026-10-31 19:49:08.746926');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('cd90eff2-2a51-4d5c-98a6-2d554f841a31', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', '3f4d2bb5-b10a-4e83-9d8b-ed0fb7869607', '2026-10-31 19:49:08.747569', '2026-10-31 19:49:08.747570');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('77e81643-e563-4e99-977d-e630c76a1d17', 'Build the HLS H.264 successive-playback test URLs', 'Combine the configured HLS video source URL, execution identifiers, logging information, the close operation, and autotest: "true" into the HTML HLS player test URL. Generate one such URL per iteration, where the number of iterations is Succesive_playback_iterations; every URL carries the same stream, so the stream is played that many times in succession.', 'A list of HLS H.264 player test URLs should be generated whose length equals Succesive_playback_iterations, with each entry pointing to the same stream.', '3f4d2bb5-b10a-4e83-9d8b-ed0fb7869607', '2026-10-31 19:49:08.748130', '2026-10-31 19:49:08.748131');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6f5a8f1f-4893-4933-a465-55be03973578', 'Store the player URLs in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated HLS H.264 successive-playback URL list>"}}. The player application reads this list and plays the URLs one after another.', 'The URL list should be stored successfully in PersistentStore.', '3f4d2bb5-b10a-4e83-9d8b-ed0fb7869607', '2026-10-31 19:49:08.748721', '2026-10-31 19:49:08.748722');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('507b7b06-c1e6-4ee5-9c29-d6f912ce5678', 'Check whether the HTML player is installed', 'Request the installed package list with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"} and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', '3f4d2bb5-b10a-4e83-9d8b-ed0fb7869607', '2026-10-31 19:49:08.749307', '2026-10-31 19:49:08.749308');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('83b62dbc-85ac-44c0-aa05-fa4a3775bf9e', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', '3f4d2bb5-b10a-4e83-9d8b-ed0fb7869607', '2026-10-31 19:49:08.749863', '2026-10-31 19:49:08.749864');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5c47c1f9-ac86-487c-ae53-2b29b89c9875', 'Download the HTML player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', '3f4d2bb5-b10a-4e83-9d8b-ed0fb7869607', '2026-10-31 19:49:08.750410', '2026-10-31 19:49:08.750411');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4c29656f-b1aa-4916-b305-1c1b29c15cd3', 'Install the HTML player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', '3f4d2bb5-b10a-4e83-9d8b-ed0fb7869607', '2026-10-31 19:49:08.750975', '2026-10-31 19:49:08.750976');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0d910cad-33eb-492e-b808-3949332e5e3c', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', '3f4d2bb5-b10a-4e83-9d8b-ed0fb7869607', '2026-10-31 19:49:08.751517', '2026-10-31 19:49:08.751517');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('edb9c810-5b35-4e1e-853b-3e167ed4689e', 'Launch the HTML player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', '3f4d2bb5-b10a-4e83-9d8b-ed0fb7869607', '2026-10-31 19:49:08.751698', '2026-10-31 19:49:08.751698');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1372103c-1747-42d1-ac36-344135d381d5', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The HTML player should appear as an active loaded application.', '3f4d2bb5-b10a-4e83-9d8b-ed0fb7869607', '2026-10-31 19:49:08.752732', '2026-10-31 19:49:08.752733');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d928db52-f3b4-415c-b615-b9a445b63d0c', 'Validate the successive HLS H.264 playback', 'Monitor the REST API application log until the final test result is reported. Count the entries containing Video Player Playing (one per playback), collect each STREAM <number> PLAYBACK RESULT : SUCCESS or FAILURE entry, and check the final TEST RESULT entry.', 'The number of Video Player Playing entries should equal Succesive_playback_iterations, every STREAM <number> entry from 1 to that count should report SUCCESS, and the final result should be TEST RESULT: SUCCESS.', '3f4d2bb5-b10a-4e83-9d8b-ed0fb7869607', '2026-10-31 19:49:08.752936', '2026-10-31 19:49:08.752936');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('663b8ccf-7e51-485a-901d-b8be46f32ead', 'Validate the post-playback resource usage', 'After successful playback, run the resource-usage validation and evaluate the returned CPU load and memory usage.', 'CPU load and memory usage should be returned and should remain within the configured limits.', '3f4d2bb5-b10a-4e83-9d8b-ed0fb7869607', '2026-10-31 19:49:08.753553', '2026-10-31 19:49:08.753554');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4bf70f9f-a32b-4eee-a21f-a083ae7c85b8', 'Terminate the HTML player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The HTML player should terminate successfully.', '3f4d2bb5-b10a-4e83-9d8b-ed0fb7869607', '2026-10-31 19:49:08.754185', '2026-10-31 19:49:08.754185');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f4f8a533-1167-48f4-9742-4f95c93392bc', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', '3f4d2bb5-b10a-4e83-9d8b-ed0fb7869607', '2026-10-31 19:49:08.755315', '2026-10-31 19:49:08.755316');
