INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('24251a85-a12c-4e18-9b1a-236413aef318', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', '2d5bf43e-8c9c-4621-b5c3-25518bf28a83', '2026-10-31 18:32:21.776616', '2026-10-31 18:32:21.776617');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e327c317-e095-4560-b8e4-fbcc36d3582d', 'Download the HTML player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', '2d5bf43e-8c9c-4621-b5c3-25518bf28a83', '2026-10-31 18:32:21.777404', '2026-10-31 18:32:21.777406');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9601f136-ed0a-4a63-940f-87451becf6d6', 'Install the HTML player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', '2d5bf43e-8c9c-4621-b5c3-25518bf28a83', '2026-10-31 18:32:21.778180', '2026-10-31 18:32:21.778181');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('729502a3-e0e3-4599-aaed-a23b24342e9d', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', '2d5bf43e-8c9c-4621-b5c3-25518bf28a83', '2026-10-31 18:32:21.779269', '2026-10-31 18:32:21.779270');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b5edcc6a-ce6d-4717-8b92-fbbff18c0b2c', 'Launch the HTML player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', '2d5bf43e-8c9c-4621-b5c3-25518bf28a83', '2026-10-31 18:32:21.780050', '2026-10-31 18:32:21.780051');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('17547a4c-ed95-4e37-aa26-2f0ff779ea2c', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The HTML player should appear as an active loaded application.', '2d5bf43e-8c9c-4621-b5c3-25518bf28a83', '2026-10-31 18:32:21.782327', '2026-10-31 18:32:21.782329');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4311b03c-4252-43a7-bbab-aaf76b659ba9', 'Validate the successive playback', 'Monitor the REST API application log until the final test result is reported. Count the entries containing Video Player Playing (one per playback), collect each STREAM <number> PLAYBACK RESULT : SUCCESS or FAILURE entry, and check the final TEST RESULT entry.', 'The number of Video Player Playing entries should equal Succesive_playback_iterations, every STREAM <number> entry from 1 to that count should report SUCCESS, and the final result should be TEST RESULT: SUCCESS.', '2d5bf43e-8c9c-4621-b5c3-25518bf28a83', '2026-10-31 18:32:21.783096', '2026-10-31 18:32:21.783097');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1fd716d7-4dfb-4584-a62e-4c67004955bb', 'Validate the post-playback resource usage', 'After successful playback, run the resource-usage validation and evaluate the returned CPU load and memory usage.', 'CPU load and memory usage should be returned and should remain within the configured limits.', '2d5bf43e-8c9c-4621-b5c3-25518bf28a83', '2026-10-31 18:32:21.783858', '2026-10-31 18:32:21.783859');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('dfda15dc-0d9d-4e68-91ae-b5640b3207ae', 'Terminate the HTML player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The HTML player should terminate successfully.', '2d5bf43e-8c9c-4621-b5c3-25518bf28a83', '2026-10-31 18:32:21.784568', '2026-10-31 18:32:21.784569');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('137843e3-eda2-4b23-98bc-29f4bf631a25', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', '2d5bf43e-8c9c-4621-b5c3-25518bf28a83', '2026-10-31 18:32:21.785304', '2026-10-31 18:32:21.785305');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8d6c2cf3-71b0-41ca-bcf9-67ceddadd49d', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', '6c09fa23-37e7-4ce9-a979-1cd8419c3cab', '2026-11-03 04:46:55.247599', '2026-11-03 04:46:55.247600');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3cde21c0-5b71-4a23-a28a-baefb34f6487', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', '6c09fa23-37e7-4ce9-a979-1cd8419c3cab', '2026-11-03 04:46:55.248629', '2026-11-03 04:46:55.248629');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c14e01fb-a0fb-46b2-9443-4a9e97aadfcb', 'Build the AV1 successive-playback test URLs', 'Combine the configured AV1 video source URL, execution identifiers, logging information, the close operation, and autotest: "true" into the HTML video player test URL. Generate one such URL per iteration, where the number of iterations is Succesive_playback_iterations; every URL carries the same stream, so the stream is played that many times in succession.', 'A list of AV1 player test URLs should be generated whose length equals Succesive_playback_iterations, with each entry pointing to the same stream.', '6c09fa23-37e7-4ce9-a979-1cd8419c3cab', '2026-11-03 04:46:55.249517', '2026-11-03 04:46:55.249518');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('46089aec-be94-4e42-9afc-83eb7bd82b08', 'Store the player URLs in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated AV1 successive-playback URL list>"}}. The player application reads this list and plays the URLs one after another.', 'The URL list should be stored successfully in PersistentStore.', '6c09fa23-37e7-4ce9-a979-1cd8419c3cab', '2026-11-03 04:46:55.250343', '2026-11-03 04:46:55.250344');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('13f6fdc8-1806-4d4d-932f-b39dd6871005', 'Check whether the HTML player is installed', 'Request the installed package list with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"} and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', '6c09fa23-37e7-4ce9-a979-1cd8419c3cab', '2026-11-03 04:46:55.251144', '2026-11-03 04:46:55.251145');
